//! The parts the chips other than the PSG are made of: instruments, the ADSR envelope,
//! a pulse oscillator with its steps band-limited, and the pitch of a note.
//!
//! The chips' settings (sound_nes.zig and the others) use these parts with their own
//! ranges, clocks, and mixers. Everything works at the output's sample rate and gives
//! the same samples for the same input.

const std = @import("std");

/// What an instrument's oscillator plays, on a chip that lets it choose (C64); a chip
/// with fixed waves takes what fits (the NES's pulse voices take the duty).
pub const Wave = enum(u8) { square, pulse, triangle, saw, noise };

/// The chips whose sound a voice can have.
pub const Chip = enum(u8) { msx, atari_st, nes, c64, scc, amiga };

/// The voices PLAY has. Each chip's sound (sound_nes.zig and the others) has this many
/// places, numbered as the voices are, so that any voice can sound like any chip.
pub const voice_slots = 8;

/// An instrument (INSTRUMENT and the words after it; MML's `@` chooses one).
pub const Instrument = struct {
    /// STYLE: the chip this instrument sounds like; without one, the chip the voice
    /// has from NES-SOUND, CHIPS, and the others.
    style: ?Chip = null,
    wave: Wave = .square,
    /// The pulse's high part, 0 to 100 percent (PULSE).
    duty: u8 = 50,
    /// ADSR as on the C64's SID: the attack, decay, and release times by the SID's
    /// table, and the sustain level, each 0 to 15.
    attack: u8 = 0,
    decay: u8 = 0,
    sustain: u8 = 15,
    release: u8 = 0,
    /// RING and SYNC: the C64's ring modulation (of the triangle) and hard sync, by
    /// the voice before this one.
    ring: bool = false,
    sync: bool = false,
    /// FILTER: 0 none, 1 low-pass, 2 band-pass, 3 high-pass; the cutoff 0 to 2047 and
    /// the resonance 0 to 15, as the SID's registers.
    filter: u8 = 0,
    cutoff: u16 = 1024,
    resonance: u8 = 0,
    /// SCC-WAVE: the 32 signed samples the SCC plays; without one it plays `wave`.
    wavetable: ?[32]i8 = null,
    /// SAMPLE-INSTRUMENT: the sample (0 to 63) the Amiga plays; without one it plays
    /// the wave as the SCC does.
    sample: ?u8 = null,

    /// The 32 samples the SCC plays: SCC-WAVE's, or `wave` made into 32 steps (the
    /// SCC has no noise: a square instead).
    pub fn table(self: Instrument) [32]i8 {
        if (self.wavetable) |samples| return samples;
        var samples: [32]i8 = undefined;
        const high: usize = switch (self.wave) {
            .pulse => @intFromFloat(@round(@as(f32, @floatFromInt(@min(self.duty, 100))) * 32.0 / 100.0)),
            else => 16,
        };
        for (&samples, 0..) |*s, i| {
            const n: i32 = @intCast(i);
            s.* = switch (self.wave) {
                .square, .pulse, .noise => if (i < high) 127 else -128,
                // Up from -128 to 127 and down again, over the 32 steps.
                .triangle => @intCast(if (n < 16) -128 + n * 17 else 127 - (n - 16) * 17),
                .saw => @intCast(-128 + n * 8 + @divTrunc(n, 4)),
            };
        }
        return samples;
    }
};

/// The SID's attack times in milliseconds for the values 0 to 15; decay and release
/// take three times as long.
const attack_ms = [16]f32{ 2, 8, 16, 24, 38, 56, 68, 80, 100, 250, 500, 800, 1000, 3000, 5000, 8000 };

/// An ADSR envelope, from 0 to 1, a sample at a time: a straight attack, then a decay
/// and a release that slow down as they go (to 1% of their way in their time, near
/// enough to the SID's curve).
pub const Adsr = struct {
    stage: enum { idle, attack, decay, sustain, release } = .idle,
    level: f32 = 0,
    attack_step: f32 = 1,
    decay_factor: f32 = 0,
    release_factor: f32 = 0,
    sustain: f32 = 1,

    pub fn start(self: *Adsr, instrument: Instrument, sample_rate: u32) void {
        const rate: f32 = @floatFromInt(sample_rate);
        self.attack_step = 1.0 / (attack_ms[instrument.attack & 15] / 1000.0 * rate);
        self.decay_factor = factor(3 * attack_ms[instrument.decay & 15], rate);
        self.release_factor = factor(3 * attack_ms[instrument.release & 15], rate);
        self.sustain = @as(f32, @floatFromInt(instrument.sustain & 15)) / 15.0;
        // The attack goes on from the level the last note left (as the SID's does).
        self.stage = .attack;
    }

    pub fn stop(self: *Adsr) void {
        if (self.stage != .idle) self.stage = .release;
    }

    /// The factor that takes a level 99% of its way in `ms` milliseconds.
    fn factor(ms: f32, rate: f32) f32 {
        return @exp(@log(@as(f32, 0.01)) / (ms / 1000.0 * rate));
    }

    pub fn next(self: *Adsr) f32 {
        switch (self.stage) {
            .idle => {},
            .attack => {
                self.level += self.attack_step;
                if (self.level >= 1) {
                    self.level = 1;
                    self.stage = .decay;
                }
            },
            .decay => {
                self.level = self.sustain + (self.level - self.sustain) * self.decay_factor;
                if (self.level - self.sustain < 0.001) {
                    self.level = self.sustain;
                    self.stage = .sustain;
                }
            },
            .sustain => {},
            .release => {
                self.level *= self.release_factor;
                if (self.level < 0.0001) {
                    self.level = 0;
                    self.stage = .idle;
                }
            },
        }
        return self.level;
    }
};

/// The correction to a step of height 2 at phase 0 for an oscillator moving `increment`
/// of its cycle a sample (PolyBLEP): it spreads the step over two samples, which keeps
/// the high harmonics from folding back as audible tones.
pub fn polyBlep(phase: f32, increment: f32) f32 {
    if (phase < increment) {
        const x = phase / increment;
        return x + x - x * x - 1;
    }
    if (phase > 1 - increment) {
        const x = (phase - 1) / increment;
        return x * x + x + x + 1;
    }
    return 0;
}

/// A pulse from 0 to 1, high for `duty` (0 to 1) of each cycle, with its two steps
/// band-limited.
pub const Pulse = struct {
    phase: f32 = 0,

    pub fn next(self: *Pulse, increment: f32, duty: f32) f32 {
        const phase = self.phase;
        var value: f32 = if (phase < duty) 1 else 0;
        value += 0.5 * polyBlep(phase, increment);
        var fall = phase - duty;
        if (fall < 0) fall += 1;
        value -= 0.5 * polyBlep(fall, increment);
        self.phase += increment;
        if (self.phase >= 1) self.phase -= 1;
        return value;
    }
};

/// The 12 semitones from A up, as ratios of frequency.
const semitone_ratios = [12]f64{ 1.0, 1.0594630943592953, 1.122462048309373, 1.189207115002721, 1.2599210498948732, 1.3348398541700344, 1.4142135623730951, 1.4983070768766815, 1.5874010519681994, 1.681792830507429, 1.7817974362806785, 1.8877486253633868 };

/// The frequency of a note (octave × 12 + semitone, as sound_mml's Event.note) in equal
/// temperament with O4's A at 440 Hz.
pub fn noteFrequency(note: u8) f64 {
    const distance = @as(i32, note) - 57;
    var frequency = 440.0 * semitone_ratios[@intCast(@mod(distance, 12))];
    var octaves = @divFloor(distance, 12);
    while (octaves > 0) : (octaves -= 1) frequency *= 2;
    while (octaves < 0) : (octaves += 1) frequency /= 2;
    return frequency;
}

/// The period register a chip whose frequency is clock / (divider × (period + offset))
/// needs for a note, rounded, within 0 to `max`.
pub fn chipPeriod(note: u8, clock: u32, divider: u32, offset: u32, max: u32) u32 {
    const exact = @as(f64, @floatFromInt(clock)) / (@as(f64, @floatFromInt(divider)) * noteFrequency(note));
    const rounded: i64 = @intFromFloat(@round(exact));
    return @intCast(std.math.clamp(rounded - offset, 0, max));
}

source_snapshots_lf.src/core/sound_engine.zig:
//! Plays MSX BASIC's PLAY and SOUND on a PSG, for a host's audio thread.
//!
//! Two threads share an Engine: the Forth program (the producer) puts notes and commands
//! into one-way queues, and the audio thread (the consumer) takes them in `render`, which
//! makes the samples. Each queue has one writer of each index, so neither side locks or
//! waits. As on the MSX, a PLAY's voices start together: each PLAY ends every voice's
//! notes with an end mark, and the next PLAY starts only when all three voices reached
//! theirs (and the producer has put all of the next one in).

const std = @import("std");
const mml = @import("sound_mml.zig");
const psg_module = @import("sound_psg.zig");
const parts = @import("sound_parts.zig");
const nes_module = @import("sound_nes.zig");
const c64_module = @import("sound_c64.zig");
const scc_module = @import("sound_scc.zig");
const amiga_module = @import("sound_amiga.zig");
pub const pcm = @import("sound_pcm.zig");
pub const stream = @import("sound_stream.zig");
pub const mod_module = @import("sound_mod.zig");

pub const Event = mml.Event;
pub const Psg = psg_module.Psg;
pub const Instrument = parts.Instrument;

/// The chip a note sounds like. The PSG runs with every chip, for SOUND and BEEP.
pub const Chip = parts.Chip;

/// How many voices a chip has of its own.
fn chipVoices(chip: Chip) usize {
    return switch (chip) {
        .msx, .atari_st => 3,
        .nes => nes_module.voice_count,
        .c64 => c64_module.voice_count,
        .scc => scc_module.voice_count,
        .amiga => amiga_module.voice_count,
    };
}

/// The chips the voices have (CHIPS; MSX-SOUND and the others choose one), which an
/// instrument without STYLE sounds like. Their voices are numbered in the order of
/// `Chip`: with the MSX and the SCC, voices 1 to 3 are the PSG's and 4 to 8 the SCC's.
/// The voices after those of the last chip sound like the last chip.
pub const Chips = struct {
    mask: u8,

    pub fn one(chip: Chip) Chips {
        return .{ .mask = bit(chip) };
    }

    fn bit(chip: Chip) u8 {
        return @as(u8, 1) << @intCast(@backingInt(chip));
    }

    pub fn has(self: Chips, chip: Chip) bool {
        return self.mask & bit(chip) != 0;
    }

    /// The chip, when only one is chosen.
    pub fn only(self: Chips) ?Chip {
        if (@popCount(self.mask) != 1) return null;
        return @fromBackingInt(@intCast(@ctz(self.mask)));
    }

    /// A mask CHIPS takes: at least one chip, and no unknown bit.
    pub fn fromMask(mask: i64) ?Chips {
        const all = (@as(i64, 1) << chip_count) - 1;
        if (mask <= 0 or mask & ~all != 0) return null;
        return .{ .mask = @intCast(mask) };
    }

    pub fn voiceCount(self: Chips) usize {
        var count: usize = 0;
        for (0..chip_count) |c| {
            const chip: Chip = @fromBackingInt(@intCast(c));
            if (self.has(chip)) count += chipVoices(chip);
        }
        return count;
    }

    /// The chip whose own voice v (from 0) is, and the voice's number on that chip.
    pub fn place(self: Chips, v: usize) ?struct { chip: Chip, voice: usize } {
        var first: usize = 0;
        for (0..chip_count) |c| {
            const chip: Chip = @fromBackingInt(@intCast(c));
            if (!self.has(chip)) continue;
            if (v < first + chipVoices(chip)) return .{ .chip = chip, .voice = v - first };
            first += chipVoices(chip);
        }
        return null;
    }

    /// The chip voice v sounds like when its instrument has no STYLE.
    pub fn chipOf(self: Chips, v: usize) Chip {
        if (self.place(v)) |at| return at.chip;
        var last: Chip = .msx;
        for (0..chip_count) |c| {
            const chip: Chip = @fromBackingInt(@intCast(c));
            if (self.has(chip)) last = chip;
        }
        return last;
    }

    /// The voice (from 0) where a chip's own voices start, if it is one of these.
    pub fn firstVoice(self: Chips, wanted: Chip) ?usize {
        if (!self.has(wanted)) return null;
        var first: usize = 0;
        for (0..chip_count) |c| {
            const chip: Chip = @fromBackingInt(@intCast(c));
            if (chip == wanted) break;
            if (self.has(chip)) first += chipVoices(chip);
        }
        return if (first < max_voices) first else null;
    }
};

const chip_count = 6;

/// The voices PLAY has; each has its queue, and can sound like any chip.
pub const max_voices = parts.voice_slots;

/// The PSGs besides `Engine.psg`: each chip's voices go three to a PSG, so there are two
/// more of its kind and three of the other kind.
const extra_psgs = 5;

/// The SFX that can sound at once; a new one takes the place of the oldest.
pub const sfx_voices = 4;

/// A queue with one producer and one consumer. `capacity` must be a power of two.
pub fn Ring(comptime T: type, comptime capacity: u32) type {
    return struct {
        const Self = @This();
        items: [capacity]T = undefined,
        /// The next item to take; only the consumer writes it.
        head: std.atomic.Value(u32) = .init(0),
        /// The next free place; only the producer writes it.
        tail: std.atomic.Value(u32) = .init(0),

        pub const size = capacity;

        /// Producer: how many items fit now.
        pub fn free(self: *const Self) u32 {
            return capacity - (self.tail.raw -% self.head.load(.acquire));
        }

        /// Producer.
        pub fn push(self: *Self, item: T) bool {
            const tail = self.tail.raw;
            if (tail -% self.head.load(.acquire) >= capacity) return false;
            self.items[tail % capacity] = item;
            self.tail.store(tail +% 1, .release);
            return true;
        }

        /// Producer: whether the consumer has taken everything.
        pub fn isEmpty(self: *const Self) bool {
            return self.head.load(.acquire) == self.tail.raw;
        }

        /// Consumer: the next item, still in the queue.
        pub fn peek(self: *const Self) ?T {
            const head = self.head.raw;
            if (head == self.tail.load(.acquire)) return null;
            return self.items[head % capacity];
        }

        /// Consumer: takes the item `peek` gave.
        pub fn drop(self: *Self) void {
            self.head.store(self.head.raw +% 1, .release);
        }

        /// Consumer: takes everything before `position`, a tail the producer had.
        pub fn dropUntil(self: *Self, position: u32) void {
            self.head.store(position, .release);
        }
    };
}

/// Notes and end marks each voice can wait with.
pub const voice_queue_size = 32;

pub const Command = union(enum) {
    /// SOUND reg, value.
    write: struct { reg: u8, value: u8 },
    /// BEEP (with `beep`) or a stop: drops the notes put before it (up to these tails
    /// and this PLAY count), sounds 1316 Hz for 40 ms when `beep`, and sets the PSG as
    /// the MSX starts it. With `chip`, PLAY plays on that chip from now on.
    reset: struct { tails: [max_voices]u32, plays: u32, beep: bool, chips: ?Chips = null, preserve_effects: bool = false },
    /// INSTRUMENT and the words after it: the instrument's settings, which the notes
    /// that start from now on use.
    instrument: struct { index: u8, value: Instrument },
    /// LOAD-SAMPLE, SAMPLE, and LOOP-SAMPLE: where sample `index` is in the pool.
    sample: struct { index: u8, value: pcm.Sample },
    /// FREE-SAMPLES, after a stop: every sample is gone.
    free_samples,
    /// SFX: plays a sample once at its rate, at once and beside the music.
    sfx: u8,
    /// AMIGA-FILTER: the LED filter on or off.
    amiga_filter: bool,
    /// LOAD-MOD: the module whose song (sound_mod.Song) is in the pool from this place
    /// (in 16-bit units). A module that plays stops.
    mod_load: u32,
    /// PLAY-MOD: plays the module from its start, again after its end when true.
    mod_play: bool,
    /// STOP-MOD.
    mod_stop,
};

/// The PSG's registers as the MSX's BIOS sets them (GICINI): R0 = 55H, the tones on and
/// the noise off (R7 = B8H), R11 = 0BH, the others 0.
pub fn msxInitialRegisters() [16]u8 {
    var regs: [16]u8 = @splat(0);
    regs[0] = 0x55;
    regs[7] = 0xb8;
    regs[11] = 0x0b;
    return regs;
}

/// BEEP: about 1316 Hz (O6's E) at volume 7 for 40 ms.
pub const beep_period: u16 = 85;
pub const beep_volume: u8 = 7;
pub const beep_milliseconds: u32 = 40;

pub const Engine = struct {
    /// The PSG of SOUND and BEEP, and of the first three voices.
    psg: Psg,
    /// The other PSGs, for the voices that use them.
    psg_extra: [extra_psgs]Psg,
    /// Bit n: `psg_extra[n]` has played since the last stop.
    psg_used: u8 = 0,
    nes: nes_module.Nes,
    c64: c64_module.C64,
    scc: scc_module.Scc,
    amiga: amiga_module.Amiga,
    sample_rate: u32,
    /// The host's pool of samples; the producer adds to its end (sound_pcm.zig).
    pool: []i16 = &.{},
    samples: [pcm.sample_count]pcm.Sample = @splat(.{}),
    amiga_led: bool = false,
    /// The voices of SFX, used in turn.
    sfx_players: [sfx_voices]pcm.Player = @splat(.{}),
    sfx_next: usize = 0,
    mod: mod_module.Mod,
    /// Whether the module plays; only the consumer writes it (MOD?).
    mod_playing: std.atomic.Value(bool) = .init(false),
    chips: Chips = Chips.one(.msx),
    /// The chips that make sound: `chips`, and those STYLE has used since the last stop.
    active: Chips = Chips.one(.msx),
    /// The chip each voice's last note played on, since the last stop.
    current: [max_voices]?Chip = @splat(null),
    instruments: [mml.instrument_count]Instrument = @splat(.{}),
    voices: [max_voices]Ring(Event, voice_queue_size) = @splat(.{}),
    commands: Ring(Command, 64) = .{},
    /// The PLAYs put in; only the producer writes it.
    plays_put: std.atomic.Value(u32) = .init(0),
    /// The PLAYs started; only the consumer writes it.
    plays_started: std.atomic.Value(u32) = .init(0),
    /// Bit n: voice n plays a note of the current PLAY; only the consumer writes it.
    sounding: std.atomic.Value(u8) = .init(0),

    /// Producer publishes PCM attachment; consumer applies at a render boundary.
    pcm_control: stream.Control = .{},
    pcm_session: @import("sound_stream_session.zig").Session = .{},

    // The consumer's own state.
    remaining: [max_voices]u16 = @splat(0),
    at_end: [max_voices]bool = @splat(true),
    tick_fraction: u32 = 0,
    beep_samples: u32 = 0,
    dc_input: [2]f32 = .{ 0, 0 },
    dc_output: [2]f32 = .{ 0, 0 },

    pub fn init(model: psg_module.Model, clock: u32, sample_rate: u32) Engine {
        var engine: Engine = .{ .psg = Psg.init(model, clock, sample_rate), .psg_extra = undefined, .nes = nes_module.Nes.init(sample_rate), .c64 = c64_module.C64.init(sample_rate), .scc = scc_module.Scc.init(sample_rate), .amiga = amiga_module.Amiga.init(sample_rate), .mod = mod_module.Mod.init(sample_rate), .sample_rate = sample_rate };
        engine.setRegisters(msxInitialRegisters());
        engine.resetVoices();
        return engine;
    }

    fn setRegisters(self: *Engine, regs: [16]u8) void {
        for (regs, 0..) |value, reg| self.psg.write(@intCast(reg), value);
    }

    /// After a stop or a change of chips: no voice has played, the other PSGs are as at
    /// start, and each chip knows which voices are its own.
    fn resetVoices(self: *Engine) void {
        const main_is_ym = self.psg.model == .ym2149;
        for (&self.psg_extra, 0..) |*psg, i| {
            const is_ym = if (i < 2) main_is_ym else !main_is_ym;
            psg.* = if (is_ym)
                Psg.init(.ym2149, psg_module.atari_st_clock, self.sample_rate)
            else
                Psg.init(.ay8910, psg_module.msx_clock, self.sample_rate);
            for (msxInitialRegisters(), 0..) |value, reg| psg.write(@intCast(reg), value);
        }
        self.psg_used = 0;
        self.active = self.chips;
        self.current = @splat(null);
        self.nes.place(self.chips.firstVoice(.nes));
        self.c64.place(self.chips.firstVoice(.c64));
        self.amiga.place(self.chips.firstVoice(.amiga));
    }

    /// Which of `psg_extra` plays voice v as `chip`, or null for `psg`.
    fn psgIndex(self: *const Engine, chip: Chip, v: usize) ?usize {
        const bank = v / 3;
        if ((chip == .atari_st) == (self.psg.model == .ym2149)) {
            return if (bank == 0) null else bank - 1;
        }
        return 2 + bank;
    }

    fn psgOf(self: *Engine, chip: Chip, v: usize) *Psg {
        return if (self.psgIndex(chip, v)) |i| &self.psg_extra[i] else &self.psg;
    }

    // ---- The producer's side (the Forth program) ----

    /// How many more items voice `voice` can take now.
    pub fn voiceFree(self: *const Engine, voice: usize) u32 {
        return self.voices[voice].free();
    }

    pub fn putEvent(self: *Engine, voice: usize, event: Event) bool {
        return self.voices[voice].push(event);
    }

    /// Lets the audio thread start the PLAY being put.
    pub fn countPlay(self: *Engine) void {
        self.plays_put.store(self.plays_put.raw +% 1, .release);
    }

    /// Ends one PLAY with an end mark in each voice (the caller has checked they fit).
    pub fn endPlay(self: *Engine) void {
        for (&self.voices) |*queue| std.debug.assert(queue.push(.{ .kind = .end }));
    }

    pub fn putCommand(self: *Engine, command: Command) bool {
        return self.commands.push(command);
    }

    /// The command for BEEP (`beep`) or a stop, which drops every note put so far.
    pub fn resetCommand(self: *const Engine, beep: bool) Command {
        var tails: [max_voices]u32 = undefined;
        for (&tails, &self.voices) |*tail, *queue| tail.* = queue.tail.raw;
        return .{ .reset = .{ .tails = tails, .plays = self.plays_put.raw, .beep = beep } };
    }

    /// Stop MML and reset its chip voices, preserving independent SFX and MOD playback.
    pub fn stopPlayCommand(self: *const Engine) Command {
        var command = self.resetCommand(false);
        command.reset.preserve_effects = true;
        return command;
    }

    /// The command for MSX-SOUND and the others: a stop that also chooses the chip.
    pub fn chipCommand(self: *const Engine, chip: Chip) Command {
        return self.chipsCommand(Chips.one(chip));
    }

    /// The command for CHIPS: a stop that also chooses the chips.
    pub fn chipsCommand(self: *const Engine, chips: Chips) Command {
        var command = self.resetCommand(false);
        command.reset.chips = chips;
        return command;
    }

    /// PLAY(n): whether voice n - 1 (or any voice, for n = 0) still has notes to play.
    pub fn isPlaying(self: *const Engine, n: usize) bool {
        if (n == 0) {
            for (1..max_voices + 1) |voice| {
                if (self.isPlaying(voice)) return true;
            }
            return false;
        }
        const voice = n - 1;
        // The consumer sets `sounding` before it takes the note, so the voice never
        // looks idle between the two.
        if (self.sounding.load(.acquire) & (@as(u8, 1) << @intCast(voice)) != 0) return true;
        return !self.voices[voice].isEmpty();
    }

    // ---- The consumer's side (the audio thread) ----

    /// Fills `out` with stereo frames (left, right) of 16-bit samples.
    pub fn render(self: *Engine, out: []i16) void {
        self.pcm_control.apply();
        self.runCommands();
        var i: usize = 0;
        while (i + 1 < out.len) : (i += 2) {
            if (self.beep_samples > 0) {
                self.beep_samples -= 1;
                if (self.beep_samples == 0) self.setRegisters(msxInitialRegisters());
            } else {
                self.tick_fraction += 50;
                if (self.tick_fraction >= self.sample_rate) {
                    self.tick_fraction -= self.sample_rate;
                    self.tick();
                }
            }
            var center = self.psg.sample() + self.sfxSample();
            if (self.psg_used != 0) {
                for (&self.psg_extra, 0..) |*psg, n| {
                    if (self.psg_used & (@as(u8, 1) << @intCast(n)) != 0) center += psg.sample();
                }
            }
            if (self.active.has(.nes)) center += self.nes.sample();
            if (self.active.has(.c64)) center += self.c64.sample();
            if (self.active.has(.scc)) center += self.scc.sample();
            var sides: [2]f32 = .{ center, center };
            if (self.active.has(.amiga)) {
                const amiga = self.amiga.sample(self.pool, self.amiga_led);
                sides[0] += amiga[0];
                sides[1] += amiga[1];
            }
            if (self.mod.playing) {
                const module = self.mod.sample(self.pool, &self.amiga_led);
                sides[0] += module[0];
                sides[1] += module[1];
            }
            const input = if (self.pcm_control.active) |active| active.sample() else stream.Frame{ .left = 0, .right = 0 };
            out[i] = stream.mix(self.filtered(0, sides[0]), input.left);
            out[i + 1] = stream.mix(self.filtered(1, sides[1]), input.right);
        }
        self.mod_playing.store(self.mod.playing, .release);
    }

    /// The level without its constant part (as the coupling capacitor of a computer's
    /// audio output removes it), as a 16-bit sample.
    fn filtered(self: *Engine, side: usize, x: f32) i16 {
        const y = x - self.dc_input[side] + 0.9985 * self.dc_output[side];
        self.dc_input[side] = x;
        self.dc_output[side] = y;
        const scaled = std.math.clamp(y * 0.6, -1.0, 1.0) * 32767.0;
        return @intFromFloat(scaled);
    }

    fn runCommands(self: *Engine) void {
        while (self.commands.peek()) |command| {
            self.commands.drop();
            switch (command) {
                .write => |w| self.psg.write(w.reg, w.value),
                .instrument => |i| self.instruments[i.index] = i.value,
                .sample => |s| self.samples[s.index] = s.value,
                .free_samples => {
                    self.samples = @splat(.{});
                    self.mod = mod_module.Mod.init(self.sample_rate);
                    self.mod_playing.store(false, .release);
                },
                .mod_load => |at| {
                    self.mod.stop();
                    const bytes = std.mem.sliceAsBytes(self.pool);
                    const start = @as(usize, at) * 2;
                    @memcpy(std.mem.asBytes(&self.mod.song), bytes[start..][0..@sizeOf(mod_module.Song)]);
                    self.mod_playing.store(false, .release);
                },
                .mod_play => |repeat| {
                    self.mod.start(repeat);
                    self.mod_playing.store(self.mod.playing, .release);
                },
                .mod_stop => {
                    self.mod.stop();
                    self.mod_playing.store(false, .release);
                },
                .amiga_filter => |on| self.amiga_led = on,
                .sfx => |n| {
                    self.sfx_players[self.sfx_next].start(self.samples[n], @as(f64, @floatFromInt(self.samples[n].rate)) / @as(f64, @floatFromInt(self.sample_rate)));
                    self.sfx_next = (self.sfx_next + 1) % sfx_voices;
                },
                .reset => |b| {
                    for (&self.voices, b.tails) |*queue, tail| queue.dropUntil(tail);
                    self.plays_started.store(b.plays, .release);
                    self.remaining = @splat(0);
                    self.at_end = @splat(true);
                    self.sounding.store(0, .release);
                    if (b.chips) |chips| {
                        self.chips = chips;
                        // The Atari ST's YM2149 runs at 2 MHz; the MSX's PSG is an AY.
                        self.psg = if (chips.has(.atari_st) and !chips.has(.msx))
                            Psg.init(.ym2149, psg_module.atari_st_clock, self.sample_rate)
                        else
                            Psg.init(.ay8910, psg_module.msx_clock, self.sample_rate);
                    }
                    self.nes = nes_module.Nes.init(self.sample_rate);
                    self.c64 = c64_module.C64.init(self.sample_rate);
                    self.scc = scc_module.Scc.init(self.sample_rate);
                    self.amiga = amiga_module.Amiga.init(self.sample_rate);
                    self.resetVoices();
                    if (!b.preserve_effects) {
                        self.sfx_players = @splat(.{});
                        self.mod.stop();
                        self.mod_playing.store(false, .release);
                    }
                    self.setRegisters(msxInitialRegisters());
                    if (b.beep) {
                        self.psg.write(0, @truncate(beep_period));
                        self.psg.write(1, @truncate(beep_period >> 8));
                        self.psg.write(8, beep_volume);
                        self.beep_samples = @max(self.sample_rate * beep_milliseconds / 1000, 1);
                    }
                },
            }
        }
    }

    /// One tick of 1/50 second: each voice counts down its note and takes the next.
    fn tick(self: *Engine) void {
        for (0..max_voices) |v| {
            if (self.remaining[v] > 0) self.remaining[v] -= 1;
            if (self.remaining[v] == 0 and !self.at_end[v]) self.nextEvent(v);
        }
        for (self.at_end) |at_end| {
            if (!at_end) return;
        }
        self.startPlay();
    }

    fn startPlay(self: *Engine) void {
        const started = self.plays_started.raw;
        if (self.plays_put.load(.acquire) == started) return;
        self.plays_started.store(started +% 1, .release);
        self.at_end = @splat(false);
        for (0..max_voices) |v| self.nextEvent(v);
    }

    fn nextEvent(self: *Engine, v: usize) void {
        // The producer puts a whole PLAY before it counts it, so the voice has an item.
        const event = self.voices[v].peek() orelse return;
        const bit = @as(u8, 1) << @intCast(v);
        switch (event.kind) {
            .end => {
                self.at_end[v] = true;
                self.silence(v);
                self.sounding.store(self.sounding.raw & ~bit, .release);
                self.voices[v].drop();
            },
            .note => {
                self.sounding.store(self.sounding.raw | bit, .release);
                self.voices[v].drop();
                self.play(v, event);
            },
        }
    }

    /// The SFX voices together, each sample once at half the full level.
    fn sfxSample(self: *Engine) f32 {
        var sum: f32 = 0;
        for (&self.sfx_players) |*player| sum += player.next(self.pool) * 0.5;
        return sum;
    }

    /// Ends voice v's note (at a rest or the end of a PLAY).
    fn silence(self: *Engine, v: usize) void {
        self.silenceOn(self.current[v] orelse self.chips.chipOf(v), v);
    }

    fn silenceOn(self: *Engine, chip: Chip, v: usize) void {
        switch (chip) {
            .msx, .atari_st => self.psgOf(chip, v).write(@intCast(8 + v % 3), 0),
            .nes => self.nes.noteOff(v),
            .c64 => self.c64.noteOff(v),
            .scc => self.scc.noteOff(v),
            .amiga => self.amiga.noteOff(v),
        }
    }

    fn play(self: *Engine, v: usize, event: Event) void {
        self.remaining[v] = event.ticks;
        if (event.period == 0) return self.silence(v);
        const volume = @min(event.amplitude, 15);
        const instrument = self.instruments[event.instrument];
        const chip = instrument.style orelse self.chips.chipOf(v);
        // A voice sounds on one chip at a time.
        if (self.current[v]) |old| {
            if (old != chip) self.silenceOn(old, v);
        }
        self.current[v] = chip;
        self.active.mask |= Chips.one(chip).mask;
        switch (chip) {
            .msx, .atari_st => {
                if (self.psgIndex(chip, v)) |n| self.psg_used |= @as(u8, 1) << @intCast(n);
                // The same note on the YM2149's 2 MHz clock.
                const period: u16 = if (chip == .msx) event.period else @intCast(parts.chipPeriod(event.note, psg_module.atari_st_clock, 16, 0, 4095));
                playPsg(self.psgOf(chip, v), v % 3, event, period);
            },
            // S (the PSG's envelope) has no meaning here: such a note plays at full volume.
            .nes => {
                if (instrument.style != null) {
                    self.nes.noteOnWave(v, event.note, volume, instrument);
                } else {
                    self.nes.noteOn(v, event.note, volume, instrument);
                }
            },
            .c64 => self.c64.noteOn(v, event.note, volume, instrument),
            .scc => self.scc.noteOn(v, event.note, volume, instrument),
            .amiga => self.amiga.noteOn(v, event.note, volume, instrument, &self.samples),
        }
    }

    fn playPsg(psg: *Psg, channel: usize, event: Event, period: u16) void {
        const reg: u8 = @intCast(channel * 2);
        psg.write(reg, @truncate(period));
        psg.write(reg + 1, @truncate(period >> 8));
        if (event.amplitude == 16) {
            psg.write(11, @truncate(event.envelope_period));
            psg.write(12, @truncate(event.envelope_period >> 8));
            psg.write(@intCast(8 + channel), 16);
            psg.write(13, event.shape);
        } else {
            psg.write(@intCast(8 + channel), event.amplitude);
        }
    }
};

/// Puts one PLAY's voices (up to 3 texts) for `engine`, a note at a time, after checking
/// all of them, so that an error puts nothing. When the voices that still have notes are
/// all full, the PLAY is let start (as the MSX does, so that a long PLAY plays while it
/// is being put) and `waitFn(context)` is called until there is room; it returns false
/// to stop, and putPlay then returns error.Interrupted: the notes put so far stay, and
/// the caller drops them with a reset command.
pub fn putPlay(engine: *Engine, voices: []mml.Voice, texts: []const []const u8, context: anytype, comptime waitFn: fn (@TypeOf(context)) bool) (mml.Error || error{Interrupted})!void {
    std.debug.assert(texts.len <= max_voices and voices.len >= texts.len);
    for (texts, 0..) |text, v| try mml.check(voices[v], text);
    var parsers: [max_voices]?mml.Parser = @splat(null);
    for (texts, 0..) |text, v| parsers[v] = mml.Parser.init(&voices[v], text);
    var pending: [max_voices]?Event = @splat(null);
    var counted = false;
    while (true) {
        var left = false;
        var progressed = false;
        for (0..max_voices) |v| {
            if (parsers[v] == null) continue;
            while (true) {
                if (pending[v] == null) pending[v] = parsers[v].?.next() catch unreachable;
                const event = pending[v] orelse {
                    parsers[v] = null;
                    break;
                };
                // Keep one place for the end mark.
                if (engine.voiceFree(v) <= 1) break;
                std.debug.assert(engine.putEvent(v, event));
                pending[v] = null;
                progressed = true;
            }
            if (parsers[v] != null) left = true;
        }
        if (!left) break;
        if (!progressed) {
            if (!counted) {
                engine.countPlay();
                counted = true;
            }
            if (!waitFn(context)) return error.Interrupted;
        }
    }
    while (!allHaveRoom(engine)) {
        if (!counted) {
            engine.countPlay();
            counted = true;
        }
        if (!waitFn(context)) return error.Interrupted;
    }
    engine.endPlay();
    if (!counted) engine.countPlay();
}

fn allHaveRoom(engine: *const Engine) bool {
    for (0..max_voices) |v| {
        if (engine.voiceFree(v) < 1) return false;
    }
    return true;
}

source_snapshots_lf.src/core/sound_psg.zig:
//! The PSG of the MSX and the Atari ST: General Instrument's AY-3-8910 and Yamaha's
//! YM2149, by their registers. Three square-wave tones, one noise, and one envelope that
//! the channels share.
//!
//! The behavior follows the data sheets and the MSX Technical Handbook (see
//! docs/SOUND_RESEARCH.md); no emulator's code is used. The chip is stepped at 1/8 of its
//! clock: a tone's output flips every `period` steps (clock / (16 × period) Hz), the
//! noise and the envelope advance every second step and every `period` steps, so a whole
//! envelope cycle is clock / (256 × period) on both chips (the AY's 16 levels last two
//! of the YM's 32 steps each). Each sample is the mean of the steps it covers, which
//! keeps the highest tones from folding back as audible noise.

pub const Model = enum { ay8910, ym2149 };

/// The MSX's clock (1.7897725 MHz) and the Atari ST's (2 MHz).
pub const msx_clock: u32 = 1_789_773;
pub const atari_st_clock: u32 = 2_000_000;

/// The AY's 16 volume levels, from Matthew Westcott's measurement of an AY-3-8910 (2001,
/// placed in the public domain): 1.147 V at level 0 up to 2.58 V at level 15, here less
/// level 0's voltage and scaled to 1.
const ay_levels = blk: {
    const volts = [16]f32{ 1.147, 1.162, 1.169, 1.178, 1.192, 1.213, 1.238, 1.299, 1.336, 1.457, 1.573, 1.707, 1.882, 2.06, 2.32, 2.58 };
    var levels: [16]f32 = undefined;
    for (volts, 0..) |v, i| levels[i] = (v - volts[0]) / (volts[15] - volts[0]);
    break :blk levels;
};

/// The YM's 32 levels: 1.5 dB apart, as the data sheet's figure shows (the fixed
/// volumes are every second level, 3 dB apart), and 0 at the bottom.
const ym_levels = blk: {
    @setEvalBranchQuota(10_000);
    var levels: [32]f32 = undefined;
    levels[0] = 0;
    for (1..32) |i| levels[i] = pow10(-1.5 * @as(f32, @floatFromInt(31 - i)) / 20.0);
    break :blk levels;
};

/// 10^x at compile time (exp of x ln 10, by its series), since @exp of a comptime float
/// is not available on every target.
fn pow10(x: f32) f32 {
    const y: f64 = @as(f64, x) * 2.302585092994046;
    var term: f64 = 1;
    var sum: f64 = 1;
    var n: f64 = 1;
    while (n < 60) : (n += 1) {
        term *= y / n;
        sum += term;
    }
    return @floatCast(sum);
}

pub const Psg = struct {
    model: Model,
    clock: u32,
    sample_rate: u32,
    regs: [16]u8 = @splat(0),
    tone_count: [3]u16 = .{ 0, 0, 0 },
    tone_high: [3]bool = .{ false, false, false },
    noise_count: u8 = 0,
    noise_half: bool = false,
    /// 17 bits; the input is bit 0 XOR bit 3, the output bit 0.
    lfsr: u32 = 1,
    env_count: u16 = 0,
    /// 31 down to 0; the level is this XOR `env_attack`.
    env_step: u8 = 31,
    env_attack: u8 = 0,
    env_hold: bool = true,
    env_alternate: bool = false,
    env_holding: bool = true,
    /// Steps (clock / 8) per sample, in units of 1 / (8 × sample_rate).
    fraction: u64 = 0,
    last: f32 = 0,

    pub fn init(model: Model, clock: u32, sample_rate: u32) Psg {
        var psg: Psg = .{ .model = model, .clock = clock, .sample_rate = sample_rate };
        psg.reset();
        return psg;
    }

    /// All registers 0 (tones and noise on, volumes 0), the noise and the envelope from
    /// their start.
    pub fn reset(self: *Psg) void {
        const model = self.model;
        const clock = self.clock;
        const rate = self.sample_rate;
        self.* = .{ .model = model, .clock = clock, .sample_rate = rate };
    }

    pub fn write(self: *Psg, reg: u8, value: u8) void {
        if (reg > 15) return;
        // The AY keeps only the bits each register has; the YM keeps all 8 (and reads
        // them back), but uses the same bits.
        const masks = [16]u8{ 0xff, 0x0f, 0xff, 0x0f, 0xff, 0x0f, 0x1f, 0xff, 0x1f, 0x1f, 0x1f, 0xff, 0xff, 0x0f, 0xff, 0xff };
        self.regs[reg] = if (self.model == .ay8910) value & masks[reg] else value;
        if (reg == 13) self.startEnvelope();
    }

    pub fn read(self: *const Psg, reg: u8) u8 {
        return if (reg > 15) 0xff else self.regs[reg];
    }

    /// Writing R13 starts the envelope again from its first step.
    fn startEnvelope(self: *Psg) void {
        const shape = self.regs[13] & 0x0f;
        self.env_attack = if (shape & 4 != 0) 0x1f else 0;
        if (shape & 8 == 0) {
            // Shapes 0 to 7: one ramp, then 0.
            self.env_hold = true;
            self.env_alternate = self.env_attack != 0;
        } else {
            self.env_hold = shape & 1 != 0;
            self.env_alternate = shape & 2 != 0;
        }
        self.env_step = 31;
        self.env_count = 0;
        self.env_holding = false;
    }

    fn tonePeriod(self: *const Psg, channel: usize) u16 {
        const period = @as(u16, self.regs[channel * 2 + 1] & 0x0f) << 8 | self.regs[channel * 2];
        return if (period == 0) 1 else period;
    }

    /// One step of 8 clocks.
    pub fn step(self: *Psg) void {
        for (0..3) |c| {
            self.tone_count[c] += 1;
            if (self.tone_count[c] >= self.tonePeriod(c)) {
                self.tone_count[c] = 0;
                self.tone_high[c] = !self.tone_high[c];
            }
        }
        self.noise_half = !self.noise_half;
        if (self.noise_half) {
            const period = @max(self.regs[6] & 0x1f, 1);
            self.noise_count += 1;
            if (self.noise_count >= period) {
                self.noise_count = 0;
                const bit = (self.lfsr ^ (self.lfsr >> 3)) & 1;
                self.lfsr = (self.lfsr >> 1) | (bit << 16);
            }
        }
        if (!self.env_holding) {
            const period = @max(@as(u16, self.regs[12]) << 8 | self.regs[11], 1);
            self.env_count += 1;
            if (self.env_count >= period) {
                self.env_count = 0;
                if (self.env_step > 0) {
                    self.env_step -= 1;
                } else {
                    if (self.env_alternate) self.env_attack ^= 0x1f;
                    if (self.env_hold) self.env_holding = true else self.env_step = 31;
                }
            }
        }
    }

    /// The envelope's level, 0 to 31.
    pub fn envelopeLevel(self: *const Psg) u8 {
        return self.env_step ^ self.env_attack;
    }

    /// One channel's output now, 0 to 1.
    pub fn channelLevel(self: *const Psg, channel: usize) f32 {
        const mixer = self.regs[7];
        const tone_off = mixer & (@as(u8, 1) << @intCast(channel)) != 0;
        const noise_off = mixer & (@as(u8, 8) << @intCast(channel)) != 0;
        const on = (self.tone_high[channel] or tone_off) and (self.lfsr & 1 != 0 or noise_off);
        if (!on) return 0;
        const amplitude = self.regs[8 + channel];
        // Nonzero fixed volumes use envelope level 2L + 1; fixed zero is mute.
        // Envelope level 1 remains available in the YM's 32-step mode.
        const fixed_level = amplitude & 0x0f;
        const step_level: u8 = if (amplitude & 0x10 != 0) self.envelopeLevel() else if (fixed_level == 0) 0 else fixed_level * 2 + 1;
        return switch (self.model) {
            .ay8910 => ay_levels[step_level >> 1],
            .ym2149 => ym_levels[step_level],
        };
    }

    /// The three channels together, 0 to 1.
    pub fn level(self: *const Psg) f32 {
        return (self.channelLevel(0) + self.channelLevel(1) + self.channelLevel(2)) / 3.0;
    }

    /// The next sample: the mean of the steps it covers (0 to 1).
    pub fn sample(self: *Psg) f32 {
        const unit: u64 = @as(u64, self.sample_rate) * 8;
        self.fraction += self.clock;
        var sum: f32 = 0;
        var count: u32 = 0;
        while (self.fraction >= unit) {
            self.fraction -= unit;
            self.step();
            sum += self.level();
            count += 1;
        }
        if (count > 0) self.last = sum / @as(f32, @floatFromInt(count));
        return self.last;
    }
};

source_snapshots_lf.src/core/words_audio.zig:
//! The audio words: REQUIRE-AUDIO, which loads them, and the SND- words, which give MSX
//! BASIC's PLAY, SOUND, and BEEP to the AUDIO library (src/audio/audio.fs).
//!
//! As with the graphics words, a dictionary that never loads them keeps the numbers of
//! its words, and its images keep their format. The notes go to the sound engine of the
//! host's audio thread (sound_engine.zig) through one-way queues; this file is the
//! producer's side. What each voice keeps from one PLAY to the next (octave, length,
//! tempo, volume) is in State.audio_voices, on this side too.

const std = @import("std");
const defs = @import("defs.zig");
const forth = @import("../forth.zig");
const graphics_input = @import("graphics_input.zig");
const library_loading = @import("library_loading.zig");
const memory_map = @import("memory_map.zig");
const mml = @import("sound_mml.zig");
const sound_engine = @import("sound_engine.zig");
const parts = @import("sound_parts.zig");
const pcm = sound_engine.pcm;
const Builtin = defs.Builtin;
const Engine = sound_engine.Engine;
const RuntimeError = defs.RuntimeError;
const Cell = memory_map.Cell;
const State = forth.State;

/// The built-in words this file executes; executeBuiltin dispatches by this list.
pub const words = [_]Builtin{ .snd_play, .snd_sound, .snd_beep, .snd_playing, .snd_device, .snd_plays, .snd_chip, .snd_instrument, .snd_wave, .snd_duty, .snd_adsr, .snd_ring, .snd_sync, .snd_filter, .snd_wavetable, .snd_load_sample, .snd_sample, .snd_loop_sample, .snd_sample_instrument, .snd_sfx, .snd_amiga_filter, .snd_free_samples, .snd_chips, .snd_load_mod, .snd_play_mod, .snd_stop_mod, .snd_mod_playing, .snd_style, .snd_pcm_open, .snd_pcm_write, .snd_pcm_queued, .snd_pcm_wait, .snd_pcm_stop, .snd_pcm_close, .snd_pcm_underruns };

/// The SND- words in the order REQUIRE-AUDIO appends them, right after the AUDIO
/// vocabulary. The order is part of the dictionary that images keep: add new words at
/// the end.
pub const definitions = [_]struct { []const u8, Builtin }{
    .{ "SND-PLAY", .snd_play },                           .{ "SND-SOUND", .snd_sound },                 .{ "SND-BEEP", .snd_beep },
    .{ "SND-PLAYING", .snd_playing },                     .{ "SND-DEVICE", .snd_device },               .{ "SND-PLAYS", .snd_plays },
    .{ "SND-CHIP", .snd_chip },                           .{ "SND-INSTRUMENT", .snd_instrument },       .{ "SND-WAVE", .snd_wave },
    .{ "SND-DUTY", .snd_duty },                           .{ "SND-ADSR", .snd_adsr },                   .{ "SND-RING", .snd_ring },
    .{ "SND-SYNC", .snd_sync },                           .{ "SND-FILTER", .snd_filter },               .{ "SND-WAVETABLE", .snd_wavetable },
    .{ "SND-LOAD-SAMPLE", .snd_load_sample },             .{ "SND-SAMPLE", .snd_sample },               .{ "SND-LOOP-SAMPLE", .snd_loop_sample },
    .{ "SND-SAMPLE-INSTRUMENT", .snd_sample_instrument }, .{ "SND-SFX", .snd_sfx },                     .{ "SND-AMIGA-FILTER", .snd_amiga_filter },
    .{ "SND-FREE-SAMPLES", .snd_free_samples },           .{ "SND-CHIPS", .snd_chips },                 .{ "SND-LOAD-MOD", .snd_load_mod },
    .{ "SND-PLAY-MOD", .snd_play_mod },                   .{ "SND-STOP-MOD", .snd_stop_mod },           .{ "SND-MOD-PLAYING", .snd_mod_playing },
    .{ "SND-STYLE", .snd_style },                         .{ "SND-PCM-OPEN", .snd_pcm_open },           .{ "SND-PCM-WRITE", .snd_pcm_write },
    .{ "SND-PCM-QUEUED", .snd_pcm_queued },               .{ "SND-PCM-WAIT", .snd_pcm_wait },           .{ "SND-PCM-STOP", .snd_pcm_stop },
    .{ "SND-PCM-CLOSE", .snd_pcm_close },                 .{ "SND-PCM-UNDERRUNS", .snd_pcm_underruns },
};

/// The words of the audio library that HELP describes; the help test checks that the
/// library defines each of them.
pub const library_words = [_][]const u8{ "PLAY", "PLAY2", "PLAY3", "PLAY?", "SOUND", "BEEP", "AUDIO?", "PLAYS", "MSX-SOUND", "ST-SOUND", "NES-SOUND", "INSTRUMENT", "SQUARE", "PULSE", "TRIANGLE", "SAW", "NOISE", "DUTY", "ADSR", "C64-SOUND", "RING", "SYNC", "FILTER", "SCC-SOUND", "SCC-WAVE", "LOAD-SAMPLE", "SAMPLE", "LOOP-SAMPLE", "SAMPLE-INSTRUMENT", "SFX", "FREE-SAMPLES", "AMIGA-SOUND", "AMIGA-FILTER", "CHIPS", "MSX", "ST", "NES", "C64", "SCC", "AMIGA", "LOAD-MOD", "PLAY-MOD", "STOP-MOD", "MOD?", "STYLE", "PCM-OPEN", "PCM-WRITE", "PCM-QUEUED", "PCM-WAIT", "PCM-STOP", "PCM-CLOSE", "PCM-UNDERRUNS" };

/// The audio library, which REQUIRE-AUDIO interprets after appending the SND- words.
pub const library = @embedFile("../audio/audio.fs");

/// The name the library has in the source file table, for LOCATE and error messages.
pub const library_name = "*audio library*";

pub const group: library_loading.Group(@TypeOf(definitions[0])) = .{
    .vocabulary = "AUDIO",
    .definitions = &definitions,
    .library_name = library_name,
    .vocabulary_address = memory_map.audio_vocabulary_address,
    .image_address = memory_map.audio_image_address,
};

/// REQUIRE-AUDIO: as REQUIRE-GRAPHICS, for the AUDIO vocabulary, the SND- words, and the
/// audio library.
pub fn requireAudio(self: *State) RuntimeError!void {
    if (!defs.audio_enabled) return error.AudioUnavailable;
    return library_loading.require(self, group, self.audio_library);
}

/// Whether REQUIRE-AUDIO has loaded the audio words and they are still in the dictionary.
pub fn audioLoaded(self: *const State) bool {
    return library_loading.isLoaded(self, group);
}

/// Whether a word is one REQUIRE-AUDIO added (HELP describes these).
pub fn isAudioWord(self: *const State, word: defs.Word) bool {
    return library_loading.isGroupWord(self, word, library_name);
}

pub fn execute(self: *State, builtin: Builtin) RuntimeError!void {
    switch (builtin) {
        .snd_pcm_open, .snd_pcm_write, .snd_pcm_queued, .snd_pcm_wait, .snd_pcm_stop, .snd_pcm_close, .snd_pcm_underruns => return @import("words_pcm.zig").execute(self, builtin),
        .snd_play => {
            var texts: [3][]const u8 = undefined;
            var v: usize = 3;
            while (v > 0) {
                v -= 1;
                texts[v] = try self.memoryRange();
            }
            try play(self, &texts);
        },
        .snd_plays => {
            const count = try self.pop();
            if (count < 0 or count > sound_engine.max_voices) return error.InvalidNumber;
            if (count == 0) {
                const engine = try getEngine(self);
                try putCommand(self, engine, engine.stopPlayCommand());
                try waitTaken(self, engine);
                return;
            }
            var texts: [sound_engine.max_voices][]const u8 = undefined;
            var v: usize = @intCast(count);
            while (v > 0) {
                v -= 1;
                texts[v] = try self.memoryRange();
            }
            try play(self, texts[0..@intCast(count)]);
        },
        .snd_chip => {
            const n = try self.pop();
            const chips = @typeInfo(sound_engine.Chip).@"enum".field_names.len;
            if (n < 0 or n >= chips) return error.InvalidNumber;
            const engine = try getEngine(self);
            const chip: sound_engine.Chip = @fromBackingInt(@intCast(n));
            try stop(self, engine, engine.chipCommand(chip));
        },
        .snd_style => {
            const n = try self.pop();
            if (n == 0) return changeInstrument(self, .{ .style = .none });
            const chips = sound_engine.Chips.fromMask(n) orelse return error.InvalidNumber;
            const chip = chips.only() orelse return error.InvalidNumber;
            try changeInstrument(self, .{ .style = .{ .chip = chip } });
        },
        .snd_instrument => {
            const n = try self.pop();
            if (n < 0 or n >= mml.instrument_count) return error.InvalidNumber;
            self.audio_instrument = @intCast(n);
        },
        .snd_wave => {
            const n = try self.pop();
            if (n < 0 or n >= @typeInfo(parts.Wave).@"enum".field_names.len) return error.InvalidNumber;
            try changeInstrument(self, .{ .wave = @fromBackingInt(@intCast(n)) });
        },
        .snd_duty => {
            const n = try self.pop();
            if (n < 0 or n > 100) return error.InvalidNumber;
            try changeInstrument(self, .{ .duty = @intCast(n) });
        },
        .snd_adsr => {
            var values: [4]u8 = undefined;
            var i: usize = 4;
            while (i > 0) {
                i -= 1;
                const n = try self.pop();
                if (n < 0 or n > 15) return error.InvalidNumber;
                values[i] = @intCast(n);
            }
            try changeInstrument(self, .{ .attack = values[0], .decay = values[1], .sustain = values[2], .release = values[3] });
        },
        .snd_ring => try changeInstrument(self, .{ .ring = try self.pop() != 0 }),
        .snd_sync => try changeInstrument(self, .{ .sync = try self.pop() != 0 }),
        .snd_filter => {
            const resonance = try self.pop();
            const cutoff = try self.pop();
            const mode = try self.pop();
            if (mode < 0 or mode > 3 or cutoff < 0 or cutoff > 2047 or resonance < 0 or resonance > 15) return error.InvalidNumber;
            try changeInstrument(self, .{ .filter = @intCast(mode), .cutoff = @intCast(cutoff), .resonance = @intCast(resonance) });
        },
        .snd_wavetable => {
            const n = try self.pop();
            const address = try self.pop();
            if (n < 0 or n >= mml.instrument_count) return error.InvalidNumber;
            const start = try self.memoryAddress(address, 32);
            var samples: [32]i8 = undefined;
            for (&samples, self.memory[start..][0..32]) |*s, byte| s.* = @bitCast(byte);
            try changeInstrumentAt(self, @intCast(n), .{ .wavetable = samples });
        },
        .snd_load_sample => {
            const n = try sampleNumber(self);
            const name = try self.memoryRange();
            try self.push(try loadSample(self, name, n));
        },
        .snd_sample => {
            const n = try sampleNumber(self);
            const rate = try self.pop();
            const bytes = try self.memoryRange();
            if (rate < 1000 or rate > 192_000) return error.InvalidNumber;
            const engine = try getEngine(self);
            const out = try poolSpace(self, engine, bytes.len);
            for (out, bytes) |*s, byte| s.* = @as(i16, @as(i8, @bitCast(byte))) * 256;
            try addSample(self, engine, n, @intCast(bytes.len), @intCast(rate));
        },
        .snd_loop_sample => {
            const n = try sampleNumber(self);
            const end = try self.pop();
            const start = try self.pop();
            const sample = &self.audio_samples[n];
            // 0 0 turns the loop off.
            if (start < 0 or end < start or end > sample.length) return error.InvalidNumber;
            sample.loop_start = @intCast(start);
            sample.loop_end = @intCast(end);
            const engine = try getEngine(self);
            try putCommand(self, engine, .{ .sample = .{ .index = n, .value = sample.* } });
        },
        .snd_sample_instrument => {
            const n = try self.pop();
            if (n < -1 or n >= pcm.sample_count) return error.InvalidNumber;
            try changeInstrument(self, .{ .sample = if (n < 0) .none else .{ .number = @intCast(n) } });
        },
        .snd_sfx => {
            const n = try sampleNumber(self);
            const engine = try getEngine(self);
            try putCommand(self, engine, .{ .sfx = n });
        },
        .snd_amiga_filter => {
            const on = try self.pop() != 0;
            const engine = try getEngine(self);
            try putCommand(self, engine, .{ .amiga_filter = on });
        },
        .snd_chips => {
            const chips = sound_engine.Chips.fromMask(try self.pop()) orelse return error.InvalidNumber;
            const engine = try getEngine(self);
            try stop(self, engine, engine.chipsCommand(chips));
        },
        .snd_load_mod => {
            const name = try self.memoryRange();
            try self.push(try loadMod(self, name));
        },
        .snd_play_mod => {
            const repeat = try self.pop() != 0;
            const engine = try getEngine(self);
            try putCommand(self, engine, .{ .mod_play = repeat });
            // MOD? is true at once.
            try waitTaken(self, engine);
        },
        .snd_stop_mod => {
            const engine = try getEngine(self);
            try putCommand(self, engine, .mod_stop);
        },
        .snd_mod_playing => {
            const engine = try getEngine(self);
            try self.push(if (engine.mod_playing.load(.acquire)) -1 else 0);
        },
        .snd_free_samples => {
            const engine = try getEngine(self);
            // The music and the SFX stop first, so that nothing reads the pool any more.
            try reset(self, engine, false);
            try putCommand(self, engine, .free_samples);
            self.audio_samples = @splat(.{});
            self.audio_pool_used = 0;
        },
        .snd_sound => {
            const value = try self.pop();
            const reg = try self.pop();
            // MSX BASIC's SOUND takes the registers 0 to 13 and values 0 to 255.
            if (reg < 0 or reg > 13 or value < 0 or value > 255) return error.InvalidNumber;
            const engine = try getEngine(self);
            try putCommand(self, engine, .{ .write = .{ .reg = @intCast(reg), .value = @intCast(value) } });
        },
        .snd_beep => {
            const engine = try getEngine(self);
            try reset(self, engine, true);
        },
        .snd_playing => {
            const n = try self.pop();
            if (n < 0 or n > sound_engine.max_voices) return error.InvalidNumber;
            const engine = try getEngine(self);
            try self.push(if (engine.isPlaying(@intCast(n))) -1 else 0);
        },
        .snd_device => {
            // Whether the sound is heard: the thread runs first, so that it has tried
            // the device.
            _ = try getEngine(self);
            const device_fn = self.writer.audio_device_fn orelse return self.push(0);
            try self.push(if (device_fn(self.writer.context)) -1 else 0);
        },
        else => unreachable,
    }
}

fn getEngine(self: *State) RuntimeError!*Engine {
    const audio_fn = self.writer.audio_fn orelse return error.HostUnavailable;
    return audio_fn(self.writer.context) orelse error.HostFailed;
}

/// Pops a sample's number, 0 to 63.
fn sampleNumber(self: *State) RuntimeError!u8 {
    const n = try self.pop();
    if (n < 0 or n >= pcm.sample_count) return error.InvalidNumber;
    return @intCast(n);
}

/// The next `count` places of the pool, or OUT OF MEMORY when it has not that many.
fn poolSpace(self: *State, engine: *Engine, count: usize) RuntimeError![]i16 {
    const used: usize = self.audio_pool_used;
    if (used > engine.pool.len or count > engine.pool.len - used) return error.MemoryExhausted;
    return engine.pool[used .. used + count];
}

/// Makes the `count` samples just written at the pool's end sample n.
fn addSample(self: *State, engine: *Engine, n: u8, count: u32, rate: u32) RuntimeError!void {
    self.audio_samples[n] = .{ .start = self.audio_pool_used, .length = count, .rate = rate };
    self.audio_pool_used += count;
    try putCommand(self, engine, .{ .sample = .{ .index = n, .value = self.audio_samples[n] } });
}

/// The THROW code of a file LOAD-SAMPLE cannot read, and of a full pool.
const sample_error_code: Cell = -276;
const memory_error_code: Cell = -257;

/// LOAD-SAMPLE: reads a WAV file's PCM into the pool as sample n. The ior: 0, the
/// file's, SAMPLE ERROR (-276) for a file that is not a WAV of 8- or 16-bit PCM, or
/// OUT OF MEMORY (-257) when the pool has no room. Nothing changes on an error.
fn loadSample(self: *State, name: []const u8, n: u8) RuntimeError!Cell {
    const engine = try getEngine(self);
    const files = try self.fileOps();
    const context = self.writer.context;
    const opened = files.open(context, name, .read_only, false);
    if (opened.ior != 0) return opened.ior;
    const fileid: Cell = @bitCast(opened.value);
    defer _ = files.close(context, fileid);
    var buffer: [4096]u8 = undefined;

    var header: [12]u8 = undefined;
    switch (readAll(files, context, fileid, &header)) {
        .bytes => |count| if (count < 12 or !std.mem.eql(u8, header[0..4], "RIFF") or !std.mem.eql(u8, header[8..12], "WAVE")) return sample_error_code,
        .ior => |ior| return ior,
    }
    var format: ?pcm.Format = null;
    while (true) {
        var chunk: [8]u8 = undefined;
        const got = switch (readAll(files, context, fileid, &chunk)) {
            .bytes => |count| count,
            .ior => |ior| return ior,
        };
        if (got < 8) return sample_error_code;
        const size: u64 = std.mem.readInt(u32, chunk[4..8], .little);
        if (std.mem.eql(u8, chunk[0..4], "data")) {
            const found = format orelse return sample_error_code;
            const frame = found.frameBytes();
            const frames: usize = @intCast(size / frame);
            const out = poolSpace(self, engine, frames) catch return memory_error_code;
            // Whole frames at a time: 4096 bytes hold a whole number of any frame size.
            var done: usize = 0;
            while (done < frames) {
                const want = @min(frames - done, buffer.len / frame) * frame;
                const count = switch (readAll(files, context, fileid, buffer[0..want])) {
                    .bytes => |c| c,
                    .ior => |ior| return ior,
                };
                done += pcm.convertFrames(found, buffer[0..count], out[done..]);
                if (count < want) break;
            }
            try addSample(self, engine, n, @intCast(done), found.rate);
            return 0;
        }
        // Other chunks are skipped; their size is padded to an even number of bytes.
        var left = size + (size & 1);
        if (std.mem.eql(u8, chunk[0..4], "fmt ")) {
            const body_size: usize = @intCast(@min(size, buffer.len));
            switch (readAll(files, context, fileid, buffer[0..body_size])) {
                .bytes => |count| if (count < body_size) return sample_error_code,
                .ior => |ior| return ior,
            }
            format = pcm.parseFormat(buffer[0..body_size]) catch return sample_error_code;
            left -= body_size;
        }
        while (left > 0) {
            const part: usize = @intCast(@min(left, buffer.len));
            switch (readAll(files, context, fileid, buffer[0..part])) {
                .bytes => |count| if (count < part) return sample_error_code,
                .ior => |ior| return ior,
            }
            left -= part;
        }
    }
}

const mod_error_code: Cell = -277;

/// LOAD-MOD: reads a ProTracker module (4 channels, 31 samples) into the pool: its
/// patterns, its samples (8-bit, as 16-bit), and its song. The ior: 0, the file's,
/// MOD ERROR (-277) for a file that is not such a module or ends in its patterns, or
/// OUT OF MEMORY (-257). A module whose samples end early keeps what is there. The
/// module that played stops; nothing else changes on an error.
fn loadMod(self: *State, name: []const u8) RuntimeError!Cell {
    const mod = sound_engine.mod_module;
    const engine = try getEngine(self);
    const files = try self.fileOps();
    const context = self.writer.context;
    const opened = files.open(context, name, .read_only, false);
    if (opened.ior != 0) return opened.ior;
    const fileid: Cell = @bitCast(opened.value);
    defer _ = files.close(context, fileid);

    var header: [mod.header_size]u8 = undefined;
    switch (readAll(files, context, fileid, &header)) {
        .bytes => |count| if (count < header.len) return mod_error_code,
        .ior => |ior| return ior,
    }
    var song = mod.parseHeader(&header) catch return mod_error_code;
    // The patterns' bytes, the samples, and the song, one after the other.
    const pattern_slots = @as(usize, song.pattern_count) * mod.pattern_size / 2;
    var frames: usize = 0;
    for (song.samples) |info| frames += info.length;
    const song_slots = (@sizeOf(mod.Song) + 1) / 2;
    const out = poolSpace(self, engine, pattern_slots + frames + song_slots) catch return memory_error_code;
    const base = self.audio_pool_used;

    switch (readAll(files, context, fileid, std.mem.sliceAsBytes(out[0..pattern_slots]))) {
        .bytes => |count| if (count < pattern_slots * 2) return mod_error_code,
        .ior => |ior| return ior,
    }
    song.patterns_at = base * 2;
    var at: usize = pattern_slots;
    var buffer: [4096]u8 = undefined;
    var ended = false;
    for (&song.samples) |*info| {
        info.start = @intCast(base + at);
        var left: usize = info.length;
        var done: usize = 0;
        while (left > 0 and !ended) {
            const part = @min(left, buffer.len);
            const count = switch (readAll(files, context, fileid, buffer[0..part])) {
                .bytes => |c| c,
                .ior => |ior| return ior,
            };
            for (out[at + done ..][0..count], buffer[0..count]) |*s, byte| s.* = @as(i16, @as(i8, @bitCast(byte))) * 256;
            done += count;
            left -= count;
            if (count < part) ended = true;
        }
        // A sample cut short by the file's end is as long as what was read.
        info.length = @intCast(done);
        if (info.loop_start + info.loop_length > info.length) {
            info.loop_start = 0;
            info.loop_length = 0;
        }
        at += done;
    }
    @memcpy(std.mem.sliceAsBytes(out[at..][0..song_slots])[0..@sizeOf(mod.Song)], std.mem.asBytes(&song));
    const song_at: u32 = @intCast(base + at);
    self.audio_pool_used = @intCast(base + at + song_slots);
    try putCommand(self, engine, .{ .mod_load = song_at });
    return 0;
}

/// Reads until `buffer` is full or the file ends: the bytes read, or the file's ior.
fn readAll(files: *const forth.FileOps, context: ?*anyopaque, fileid: Cell, buffer: []u8) union(enum) { bytes: usize, ior: Cell } {
    var used: usize = 0;
    while (used < buffer.len) {
        const result = files.read(context, fileid, buffer[used..]);
        if (result.ior != 0) return .{ .ior = result.ior };
        if (result.value == 0) break;
        used += @intCast(result.value);
    }
    return .{ .bytes = used };
}

/// Which settings of the instrument being edited change.
const Change = struct {
    style: ?union(enum) { none, chip: sound_engine.Chip } = null,
    wave: ?parts.Wave = null,
    duty: ?u8 = null,
    attack: ?u8 = null,
    decay: ?u8 = null,
    sustain: ?u8 = null,
    release: ?u8 = null,
    ring: ?bool = null,
    sync: ?bool = null,
    filter: ?u8 = null,
    cutoff: ?u16 = null,
    resonance: ?u8 = null,
    wavetable: ?[32]i8 = null,
    sample: ?union(enum) { none, number: u8 } = null,
};

/// Changes the instrument INSTRUMENT chose, here and for the audio thread.
fn changeInstrument(self: *State, change: Change) RuntimeError!void {
    return changeInstrumentAt(self, self.audio_instrument, change);
}

/// Changes instrument `index`, here and for the audio thread.
fn changeInstrumentAt(self: *State, index: u8, change: Change) RuntimeError!void {
    const instrument = &self.audio_instruments[index];
    if (change.style) |value| instrument.style = switch (value) {
        .none => null,
        .chip => |chip| chip,
    };
    if (change.wave) |value| instrument.wave = value;
    if (change.duty) |value| instrument.duty = value;
    if (change.attack) |value| instrument.attack = value;
    if (change.decay) |value| instrument.decay = value;
    if (change.sustain) |value| instrument.sustain = value;
    if (change.release) |value| instrument.release = value;
    if (change.ring) |value| instrument.ring = value;
    if (change.sync) |value| instrument.sync = value;
    if (change.filter) |value| instrument.filter = value;
    if (change.cutoff) |value| instrument.cutoff = value;
    if (change.resonance) |value| instrument.resonance = value;
    if (change.wavetable) |value| instrument.wavetable = value;
    if (change.sample) |value| instrument.sample = switch (value) {
        .none => null,
        .number => |n| n,
    };
    const engine = try getEngine(self);
    try putCommand(self, engine, .{ .instrument = .{ .index = index, .value = instrument.* } });
}

/// PLAY: checks the voices' MML (an error puts nothing), then puts their notes,
/// waiting while the queues are full. Ctrl+C while it waits drops every note put so far,
/// as BEEP does without its sound, and throws USER INTERRUPT.
fn play(self: *State, texts: []const []const u8) RuntimeError!void {
    for (texts, 0..) |text, v| mml.check(self.audio_voices[v], text) catch return error.InvalidMml;
    const engine = try getEngine(self);
    var waiter: Waiter = .{ .state = self };
    sound_engine.putPlay(engine, &self.audio_voices, texts, &waiter, Waiter.wait) catch |err| switch (err) {
        error.InvalidMml => unreachable,
        error.Interrupted => {
            reset(self, engine, false) catch |reset_error| {
                if (reset_error != error.UserInterrupt) return reset_error;
            };
            return waiter.failure orelse error.UserInterrupt;
        },
    };
}

/// Drops the notes put so far and sets the PSG as the MSX starts it, sounding BEEP's
/// tone when `beep`; the voices' octave, length, tempo, and volume go back to MSX
/// BASIC's defaults. It returns when the audio thread has taken the command, so that
/// PLAY? is false at once.
fn reset(self: *State, engine: *Engine, beep: bool) RuntimeError!void {
    try stop(self, engine, engine.resetCommand(beep));
}

/// Puts a reset command (BEEP's, a stop's, or MSX-SOUND's and the others') and waits
/// until the audio thread has taken it.
fn stop(self: *State, engine: *Engine, command: sound_engine.Command) RuntimeError!void {
    self.audio_voices = @splat(.{});
    try putCommand(self, engine, command);
    try waitTaken(self, engine);
}

/// Waits until the audio thread has taken the commands put so far. It takes them every
/// few milliseconds; Ctrl+C is not taken here (the waits are short). The bound only
/// guards against a host whose thread has stopped.
fn waitTaken(self: *State, engine: *Engine) RuntimeError!void {
    var waiter: Waiter = .{ .state = self };
    var waits: usize = 0;
    while (!engine.commands.isEmpty() and waits < max_reset_waits) : (waits += 1) {
        if (!waiter.wait()) {
            if (waiter.failure) |failure| if (failure != error.UserInterrupt) return failure;
        }
    }
    if (!engine.commands.isEmpty()) return error.HostFailed;
}

/// About a second of the host's waits.
const max_reset_waits = 300;

fn putCommand(self: *State, engine: *Engine, command: sound_engine.Command) RuntimeError!void {
    var waiter: Waiter = .{ .state = self };
    while (!engine.putCommand(command)) {
        if (!waiter.wait()) return waiter.failure orelse error.UserInterrupt;
    }
}

/// Waits for the audio thread through the host, and notices Ctrl+C.
const Waiter = struct {
    state: *State,
    failure: ?RuntimeError = null,

    fn wait(self: *Waiter) bool {
        const state = self.state;
        const wait_fn = state.writer.audio_wait_fn orelse {
            self.failure = error.HostUnavailable;
            return false;
        };
        switch (wait_fn(state.writer.context)) {
            .host_failed => {
                self.failure = error.HostFailed;
                return false;
            },
            .waited => return true,
            .interrupted => {
                self.failure = error.UserInterrupt;
                return false;
            },
            .read_input => {
                // Keys read here stay for INKEY; Ctrl+C throws.
                graphics_input.readPending(state) catch |err| {
                    self.failure = err;
                    return false;
                };
                return true;
            },
        }
    }
};

