//! Public PCM primitives. Validate before effects; all consumer storage is host-owned.
const std = @import("std");
const forth = @import("../forth.zig");
const defs = @import("defs.zig");
const base = @import("runtime_base.zig");
const Engine = @import("sound_engine.zig").Engine;
const Session = @import("sound_stream_session.zig").Session;
const State = forth.State;
const Cell = forth.Cell;
const Error = forth.RuntimeError;

fn engineOf(self: *State) Error!*Engine {
    const callback = self.writer.audio_fn orelse return error.HostUnavailable;
    return callback(self.writer.context) orelse error.HostFailed;
}
fn owned(self: *State, id: Cell) Error!?*Engine {
    if (self.writer.audio_fn == null) return error.HostUnavailable;
    if (id <= 0 or self.audio_pcm_handle != id) return null;
    const engine = try engineOf(self);
    if (!engine.pcm_session.matches(@intFromPtr(self), id)) {
        self.audio_pcm_handle = 0;
        return null;
    }
    engine.pcm_session.refresh(&engine.pcm_control);
    return engine;
}
fn result(self: *State, consumed: usize, value: Cell, ior: Cell) Error!void {
    self.data_depth -= consumed;
    try self.push(value);
    try self.push(ior);
}
fn single(self: *State, ior: Cell) Error!void {
    self.data_depth -= 1;
    try self.push(ior);
}

pub fn execute(self: *State, builtin: defs.Builtin) Error!void {
    switch (builtin) {
        .snd_pcm_open => {
            try self.requireDepth(3);
            const hz = try self.peek(2);
            const channels = try self.peek(1);
            const capacity = try self.peek(0);
            if (hz < 8000 or hz > 192000 or channels < 1 or channels > 2 or capacity < 256 or capacity > 65536 or
                !@import("sound_stream.zig").validCapacity(@intCast(hz), @intCast(capacity))) return error.InvalidNumber;
            if (self.writer.audio_scope_ops == null or self.writer.standard_clock == null or self.writer.audio_wait_fn == null) return error.HostUnavailable;
            const engine = try engineOf(self);
            if (self.audio_pcm_handle != 0 and !engine.pcm_session.matches(@intFromPtr(self), self.audio_pcm_handle)) self.audio_pcm_handle = 0;
            if (self.audio_pcm_handle != 0) return result(self, 3, 0, -528);
            const opened = try engine.pcm_session.open(&engine.pcm_control, @intFromPtr(self), @intCast(hz), @intCast(channels), @intCast(capacity), engine.sample_rate);
            if (opened.ior == 0) self.audio_pcm_handle = opened.id;
            try result(self, 3, opened.id, opened.ior);
        },
        .snd_pcm_write => {
            try self.requireDepth(3);
            const address = try self.peek(2);
            const frames = try self.peek(1);
            const id = try self.peek(0);
            if (frames < 0) return error.InvalidNumber;
            const engine = (try owned(self, id)) orelse return result(self, 3, 0, -521);
            const session = &engine.pcm_session;
            if (!session.writable()) return result(self, 3, 0, -534);
            var bytes: []const u8 = &.{};
            if (frames != 0) {
                const product = @mulWithOverflow(@as(u64, @intCast(frames)), @as(u64, session.transport.channels) * 2);
                if (product[1] != 0 or product[0] > std.math.maxInt(usize)) return error.InvalidAddress;
                const length: usize = @intCast(product[0]);
                const start = try self.memoryAddress(address, length);
                bytes = self.memory[start..][0..length];
            }
            const copied = session.transport.write(bytes, @intCast(frames)) catch return error.HostFailed;
            try result(self, 3, @intCast(copied), 0);
        },
        .snd_pcm_queued, .snd_pcm_underruns => {
            try self.requireDepth(1);
            if (self.data_depth >= self.data_stack.len) return error.StackOverflow;
            const engine = (try owned(self, try self.peek(0))) orelse return result(self, 1, 0, -521);
            const session = &engine.pcm_session;
            const value: Cell = if (builtin == .snd_pcm_queued) session.transport.queued() else if (!engine.pcm_control.completed(session.request) and !session.detached) 0 else session.transport.underruns.load(.acquire);
            try result(self, 1, value, 0);
        },
        .snd_pcm_wait, .snd_pcm_stop => {
            try self.requireDepth(3);
            const argument = try self.peek(2);
            const milliseconds = try self.peek(1);
            const id = try self.peek(0);
            if (argument < 0 or (builtin == .snd_pcm_stop and argument > 1)) return error.InvalidNumber;
            const engine = (try owned(self, id)) orelse return result(self, 3, 0, -521);
            const session = &engine.pcm_session;
            if (builtin == .snd_pcm_wait) {
                if (argument == 0 or argument > session.transport.frames.len) return error.InvalidNumber;
                if (!session.writable()) return result(self, 3, 0, -534);
            } else {
                if (session.phase == .closing) return result(self, 3, 0, -534);
                if (session.phase == .stopped) return result(self, 3, -1, 0);
            }
            const ready = try waitFor(self, engine, if (builtin == .snd_pcm_wait) .space else .stop, argument, milliseconds);
            try result(self, 3, if (ready) -1 else 0, 0);
        },
        .snd_pcm_close => {
            try self.requireDepth(1);
            const engine = (try owned(self, try self.peek(0))) orelse return single(self, -521);
            const session = &engine.pcm_session;
            if (session.phase != .stopped) {
                const completed = waitFor(self, engine, .close, 0, 1000) catch |err| {
                    if (err == error.UserInterrupt) return single(self, -516);
                    return err;
                };
                if (!completed) return single(self, -528);
            }
            // Commit only after the whole-operation interrupt scope restored.
            session.commitClose(&engine.pcm_control);
            self.audio_pcm_handle = 0;
            try single(self, 0);
        },
        else => unreachable,
    }
}
const Kind = enum { space, stop, close };
fn waitFor(self: *State, engine: *Engine, kind: Kind, argument: Cell, milliseconds: Cell) Error!bool {
    const ops = self.writer.audio_scope_ops orelse return error.HostUnavailable;
    const clock = self.writer.standard_clock orelse return error.HostUnavailable;
    const sleep = self.writer.audio_wait_fn orelse return error.HostUnavailable;
    try ops.begin(self.writer.context, self);
    const session = &engine.pcm_session;
    if (kind == .close) session.beginClose();
    if (kind == .stop and argument == 1 and session.writable()) session.transport.draining.store(true, .release);
    const outcome = loop(self, engine, ops, clock, sleep, kind, argument, milliseconds);
    // An uncommitted drain timeout/error returns to running. A published detach
    // keeps suppression until ack and the next OPEN's quiescent initialization.
    if (kind == .stop and !session.detached) session.transport.draining.store(false, .release);
    ops.end(self.writer.context, self) catch |end_error| {
        if (end_error != error.UserInterrupt) return end_error;
        if (outcome) |_| {} else |work_error| if (work_error != error.UserInterrupt) return work_error;
        return end_error;
    };
    return outcome;
}
fn loop(self: *State, engine: *Engine, ops: *const @import("host_interface.zig").ExecutionOps, clock: base.Clock, sleep: *const fn (?*anyopaque) forth.AudioWait, kind: Kind, argument: Cell, milliseconds: Cell) Error!bool {
    const deadline = try base.Deadline.afterMilliseconds(try clock.now(), milliseconds);
    const session = &engine.pcm_session;
    while (true) {
        try ops.poll(self.writer.context, self);
        session.refresh(&engine.pcm_control);
        const ready = switch (kind) {
            .space => session.transport.free() >= @as(u64, @intCast(argument)),
            .stop => if (argument == 1 and !session.detached and session.transport.queued() != 0) false else try session.tryDetach(&engine.pcm_control, false),
            .close => try session.tryDetach(&engine.pcm_control, true),
        };
        if (ready) return true;
        if (deadline.expired(try clock.now())) return false;
        switch (sleep(self.writer.context)) {
            .host_failed => return error.HostFailed,
            .interrupted => return error.UserInterrupt,
            .waited, .read_input => {}, // scope.poll preserves raw input itself.
        }
    }
}

source_snapshots_lf.src/audio/audio.fs:
\ The audio library of FORTH/Sigma, written in Forth.
\
\ REQUIRE-AUDIO interprets this file, which is built into the program, after it has put
\ the SND- words in the AUDIO vocabulary. While the file loads, new words go into AUDIO,
\ AUDIO is searched first, and BASE is decimal; afterwards the search order, the current
\ word list, and BASE are what they were before REQUIRE-AUDIO.
\
\ To try a changed copy of this file without rebuilding, load the built-in one first
\ and then include the copy into AUDIO (its words then replace the built-in ones):
\   REQUIRE-AUDIO  ALSO AUDIO DEFINITIONS  DECIMAL  INCLUDE src/audio/audio.fs
\
\ The SND- words underneath:
\   SND-PLAY ( c-addr1 u1 c-addr2 u2 c-addr3 u3 -- )  the three voices of one PLAY
\   SND-SOUND ( reg value -- )  SND-BEEP ( -- )  SND-PLAYING ( n -- flag )
\   SND-DEVICE ( -- flag )  SND-PLAYS ( c-addr1 u1 ... c-addrn un n -- )
\     n=0 stops MML and resets its chip voices, keeping SFX/MOD and MML settings.
\   SND-CHIP ( n -- )  SND-INSTRUMENT ( n -- )  SND-WAVE ( n -- )
\   SND-DUTY ( percent -- )  SND-ADSR ( a d s r -- )  SND-RING ( flag -- )
\   SND-SYNC ( flag -- )  SND-FILTER ( mode cutoff resonance -- )
\   SND-WAVETABLE ( c-addr n -- )  SND-LOAD-SAMPLE ( c-addr u n -- ior )
\   SND-SAMPLE ( c-addr u rate n -- )  SND-LOOP-SAMPLE ( start end n -- )
\   SND-SAMPLE-INSTRUMENT ( n -- )  SND-SFX ( n -- )  SND-AMIGA-FILTER ( flag -- )
\   SND-FREE-SAMPLES ( -- )  SND-CHIPS ( mask -- )  SND-LOAD-MOD ( c-addr u -- ior )
\   SND-PLAY-MOD ( flag -- )  SND-STOP-MOD ( -- )  SND-MOD-PLAYING ( -- flag )
\   SND-STYLE ( chip -- )
\
\ The sound is MSX BASIC's: an AY-3-8910 at the MSX's clock, played by the host's audio
\ thread. PLAY takes MSX BASIC's music macro language (MML) and returns as soon as the
\ notes fit in the queues (32 places for each voice); the music goes on while the
\ program runs.

\ ---- MSX BASIC -------------------------------------------------------------------

: PLAY ( c-addr u -- )   0 0 0 0 SND-PLAY ;
: PLAY2 ( c-addr1 u1 c-addr2 u2 -- )   0 0 SND-PLAY ;
: PLAY3 ( c-addr1 u1 c-addr2 u2 c-addr3 u3 -- )   SND-PLAY ;
: PLAY? ( n -- flag )   SND-PLAYING ;
: SOUND ( reg value -- )   SND-SOUND ;
: BEEP ( -- )   SND-BEEP ;

\ ---- Chips ----------------------------------------------------------------------
\
\ PLAY has 8 voices. These words say which chip the voices sound like; an instrument
\ with STYLE sounds like its own chip on any voice. Choosing them stops the music, as
\ BEEP does without its sound; the PSG of SOUND and BEEP sounds with every chip.

: MSX-SOUND ( -- )   0 SND-CHIP ;     \ the MSX's AY-3-8910, 3 voices (at start)
: ST-SOUND ( -- )   1 SND-CHIP ;      \ the Atari ST's YM2149 at 2 MHz, 3 voices
: NES-SOUND ( -- )   2 SND-CHIP ;     \ the NES: pulse, pulse, triangle, noise
: C64-SOUND ( -- )   3 SND-CHIP ;     \ the C64's SID (PAL), 3 voices
: SCC-SOUND ( -- )   4 SND-CHIP ;     \ Konami's SCC, 5 voices
: AMIGA-SOUND ( -- )   5 SND-CHIP ;   \ the Amiga's Paula (PAL): samples, 4 voices
: PLAYS ( c-addr1 u1 ... c-addrn un n -- )   SND-PLAYS ;

\ Several chips together: CHIPS takes their bits, e.g. MSX SCC OR CHIPS, and numbers
\ the voices in this order (there voices 1 to 3 are the PSG's, 4 to 8 the SCC's). The
\ voices after the last chip's own sound like the last chip; voices past the 8th are
\ not played.

1 CONSTANT MSX   2 CONSTANT ST   4 CONSTANT NES   8 CONSTANT C64
16 CONSTANT SCC   32 CONSTANT AMIGA
: CHIPS ( mask -- )   SND-CHIPS ;

\ The chip the instrument INSTRUMENT chose sounds like, on any voice: one of the
\ constants above, or 0 for the chip of the voice that plays it.
: STYLE ( chip -- )   SND-STYLE ;

\ ---- Instruments ----------------------------------------------------------------
\
\ MML's @n plays with instrument n (0 to 63) on the chips that have instruments (the
\ NES, the C64, the SCC, and the Amiga). INSTRUMENT chooses the one the words after it change, e.g.
\   1 INSTRUMENT  PULSE 25 DUTY  0 6 8 4 ADSR
\   2 INSTRUMENT  SAW  1 400 8 FILTER       ( the C64: low-pass, cutoff, resonance )

: INSTRUMENT ( n -- )   SND-INSTRUMENT ;
: SQUARE ( -- )   0 SND-WAVE ;
: PULSE ( -- )   1 SND-WAVE ;
: TRIANGLE ( -- )   2 SND-WAVE ;
: SAW ( -- )   3 SND-WAVE ;
: NOISE ( -- )   4 SND-WAVE ;
: DUTY ( percent -- )   SND-DUTY ;
: ADSR ( attack decay sustain release -- )   SND-ADSR ;
: RING ( flag -- )   SND-RING ;
: SYNC ( flag -- )   SND-SYNC ;
: FILTER ( mode cutoff resonance -- )   SND-FILTER ;
\ The SCC plays instrument n with the 32 signed bytes at c-addr as its wave.
: SCC-WAVE ( c-addr n -- )   SND-WAVETABLE ;

\ ---- Samples --------------------------------------------------------------------
\
\ Samples 0 to 63 are recorded sound in the host's pool (64 MiB, outside the
\ dictionary's memory). The Amiga plays an instrument's sample with its notes, O4's C
\ at the sample's own rate; SFX plays one at once beside the music, on any chip.

: LOAD-SAMPLE ( c-addr u n -- )   SND-LOAD-SAMPLE THROW ;   \ a WAV file, 8 or 16 bits
: SAMPLE ( c-addr u rate n -- )   SND-SAMPLE ;              \ signed 8-bit bytes
: LOOP-SAMPLE ( start end n -- )   SND-LOOP-SAMPLE ;        \ 0 0 for no loop
: SAMPLE-INSTRUMENT ( n -- )   SND-SAMPLE-INSTRUMENT ;      \ -1 for none
: SFX ( n -- )   SND-SFX ;
: FREE-SAMPLES ( -- )   SND-FREE-SAMPLES ;                  \ stops the music too
: AMIGA-FILTER ( flag -- )   SND-AMIGA-FILTER ;             \ the LED filter

\ ---- Modules ----------------------------------------------------------------------
\
\ A ProTracker module (MOD, 4 channels) plays beside PLAY and SFX, on the Amiga's
\ periods and filters; its data is in the pool of samples, which FREE-SAMPLES empties.

: LOAD-MOD ( c-addr u -- )   SND-LOAD-MOD THROW ;
: PLAY-MOD ( flag -- )   SND-PLAY-MOD ;     \ again from the start after the end when true
: STOP-MOD ( -- )   SND-STOP-MOD ;
: MOD? ( -- flag )   SND-MOD-PLAYING ;

\ ---- The device ------------------------------------------------------------------

: AUDIO? ( -- flag )   SND-DEVICE ;

\ Streaming PCM (host-owned bounded frames).
: PCM-OPEN SND-PCM-OPEN ;
: PCM-WRITE SND-PCM-WRITE ;
: PCM-QUEUED SND-PCM-QUEUED ;
: PCM-WAIT SND-PCM-WAIT ;
: PCM-STOP SND-PCM-STOP ;
: PCM-CLOSE SND-PCM-CLOSE ;
: PCM-UNDERRUNS SND-PCM-UNDERRUNS ;

source_snapshots_lf.examples/ym2149.fs:
\ Original declared YM2149/ST model. No real peripheral I/O or ROM fidelity.
S" examples/ym2149-levels.fs" INCLUDED
DECIMAL
2000000 CONSTANT YM-CPU 48000 CONSTANT YM-RATE
16746496 CONSTANT YM-SELECT-ADDRESS 16746498 CONSTANT YM-DATA-ADDRESS
CREATE YM-REGS 16 CELLS ALLOT
CREATE YM-TONE-COUNT 3 CELLS ALLOT CREATE YM-TONE-HIGH 3 CELLS ALLOT
CREATE YM-PINS 2 CELLS ALLOT
VARIABLE YM-NOISE-COUNT VARIABLE YM-NOISE-HALF VARIABLE YM-LFSR
VARIABLE YM-ENV-COUNT VARIABLE YM-ENV-STEP VARIABLE YM-ENV-ATTACK
VARIABLE YM-ENV-HOLD VARIABLE YM-ENV-ALTERNATE VARIABLE YM-ENV-HOLDING
VARIABLE YM-CYCLE VARIABLE YM-DIV VARIABLE YM-FRACTION VARIABLE YM-SLOW
VARIABLE YM-SELECT
CREATE YM-EVENTS 3072 CELLS ALLOT VARIABLE YM-EVENT-COUNT VARIABLE YM-EVENT-INDEX
: YM-R@ ( reg -- byte ) CELLS YM-REGS + @ ;
: YM-RESET ( -- )
  YM-REGS 16 CELLS 0 FILL YM-TONE-COUNT 3 CELLS 0 FILL YM-TONE-HIGH 3 CELLS 0 FILL
  255 YM-PINS ! 255 YM-PINS CELL+ !
  0 YM-NOISE-COUNT ! 0 YM-NOISE-HALF ! 1 YM-LFSR !
  0 YM-ENV-COUNT ! 31 YM-ENV-STEP ! 0 YM-ENV-ATTACK !
  TRUE YM-ENV-HOLD ! FALSE YM-ENV-ALTERNATE ! TRUE YM-ENV-HOLDING !
  0 YM-CYCLE ! 0 YM-DIV ! 0 YM-FRACTION ! FALSE YM-SLOW !
  0 YM-SELECT ! 0 YM-EVENT-COUNT ! 0 YM-EVENT-INDEX ! ;
: YM-TONE-PERIOD ( channel -- steps ) 2 * DUP YM-R@ SWAP 1+ YM-R@ 15 AND 8 LSHIFT OR 1 MAX ;
: YM-NOISE-PERIOD ( -- steps ) 6 YM-R@ 31 AND 1 MAX ;
: YM-ENV-PERIOD ( -- steps ) 11 YM-R@ 12 YM-R@ 8 LSHIFT OR 1 MAX ;
: YM-ENV-LEVEL ( -- level ) YM-ENV-STEP @ YM-ENV-ATTACK @ XOR ;
: YM-ENV-START { | shape -- }
  13 YM-R@ 15 AND TO shape
  shape 4 AND IF 31 ELSE 0 THEN YM-ENV-ATTACK !
  shape 8 AND 0= IF TRUE YM-ENV-HOLD ! YM-ENV-ATTACK @ 0<> YM-ENV-ALTERNATE !
  ELSE shape 1 AND 0<> YM-ENV-HOLD ! shape 2 AND 0<> YM-ENV-ALTERNATE ! THEN
  31 YM-ENV-STEP ! 0 YM-ENV-COUNT ! FALSE YM-ENV-HOLDING ! ;
: YM-ENV-NEXT ( -- )
  YM-ENV-STEP @ 0> IF -1 YM-ENV-STEP +! ELSE
    YM-ENV-ALTERNATE @ IF YM-ENV-ATTACK @ 31 XOR YM-ENV-ATTACK ! THEN
    YM-ENV-HOLD @ IF TRUE YM-ENV-HOLDING ! ELSE 31 YM-ENV-STEP ! THEN
  THEN ;
: YM-NOISE-NEXT ( -- )
  YM-LFSR @ DUP 3 RSHIFT XOR 1 AND 16 LSHIFT YM-LFSR @ 1 RSHIFT OR YM-LFSR ! ;
: YM-STEP-LIMIT { steps -- n }
  3 0 DO I YM-TONE-PERIOD YM-TONE-COUNT I CELLS + @ - 1 MAX steps MIN TO steps LOOP
  YM-NOISE-PERIOD YM-NOISE-COUNT @ - 1 MAX 2 * 1 - YM-NOISE-HALF @ + steps MIN TO steps
  YM-ENV-HOLDING @ 0= IF YM-ENV-PERIOD YM-ENV-COUNT @ - 1 MAX steps MIN TO steps THEN steps ;
: YM-ADVANCE-STEPS { steps | count noise -- }
  3 0 DO
    YM-TONE-COUNT I CELLS + @ steps + TO count
    count I YM-TONE-PERIOD >= IF 0 TO count YM-TONE-HIGH I CELLS + DUP @ 0= SWAP ! THEN
    count YM-TONE-COUNT I CELLS + !
  LOOP
  steps 1 + YM-NOISE-HALF @ - 2 / TO noise
  YM-NOISE-HALF @ steps 1 AND + 1 AND YM-NOISE-HALF !
  noise IF
    YM-NOISE-COUNT @ noise + DUP YM-NOISE-PERIOD >= IF DROP 0 YM-NOISE-NEXT THEN YM-NOISE-COUNT !
  THEN
  YM-ENV-HOLDING @ 0= IF
    YM-ENV-COUNT @ steps + DUP YM-ENV-PERIOD >= IF DROP 0 YM-ENV-NEXT THEN YM-ENV-COUNT !
  THEN ;
: YM-FAST-STEPS { steps | n -- }
  BEGIN steps 0> WHILE steps YM-STEP-LIMIT TO n n YM-ADVANCE-STEPS n NEGATE +TO steps REPEAT ;
: YM-RAW-RUN { clocks | steps -- }
  clocks 0< clocks 9223372036854775807 YM-CYCLE @ - > OR IF -24 THROW THEN
  YM-SLOW @ IF
    clocks 0 ?DO YM-DIV @ 1+ DUP 8 = IF DROP 0 1 YM-ADVANCE-STEPS THEN YM-DIV ! LOOP
  ELSE
    YM-DIV @ clocks + 8 /MOD TO steps YM-DIV ! steps YM-FAST-STEPS
  THEN clocks YM-CYCLE +! ;
: YM-RAW-TO ( tick -- ) DUP YM-CYCLE @ < IF -24 THROW THEN YM-CYCLE @ - YM-RAW-RUN ;
: YM-CHECK { value target tick -- }
  value 0 256 WITHIN target 0 20 WITHIN AND 0= IF -24 THROW THEN
  tick YM-CYCLE @ < IF -24 THROW THEN ;
: YM-CHECK-REG ( reg -- ) 0 16 WITHIN 0= IF -24 THROW THEN ;
: YM-CHECK-PORT ( port -- ) 0 2 WITHIN 0= IF -24 THROW THEN ;
: YM-STORE { value target -- }
  target 16 < IF value target CELLS YM-REGS + ! target 13 = IF YM-ENV-START THEN EXIT THEN
  target 18 < IF value target 16 - CELLS YM-PINS + ! EXIT THEN
  target 18 = IF
    value YM-SELECT ! EXIT
  THEN
  YM-SELECT @ 16 < IF value YM-SELECT @ CELLS YM-REGS + ! YM-SELECT @ 13 = IF YM-ENV-START THEN THEN ;
: YM-COMPACT ( -- )
  YM-EVENT-INDEX @ 3 * CELLS YM-EVENTS + YM-EVENTS YM-EVENT-COUNT @ YM-EVENT-INDEX @ - 3 * CELLS MOVE
  YM-EVENT-INDEX @ NEGATE YM-EVENT-COUNT +! 0 YM-EVENT-INDEX ! ;
: YM-QUEUE { value target tick | entry -- }
  value target tick YM-CHECK
  YM-EVENT-COUNT @ YM-EVENT-INDEX @ - 1024 >= IF -528 THROW THEN
  YM-EVENT-COUNT @ IF YM-EVENT-COUNT @ 1- 3 * 2 + CELLS YM-EVENTS + @ tick > IF -24 THROW THEN THEN
  YM-EVENT-COUNT @ 1024 >= IF YM-COMPACT THEN
  YM-EVENT-COUNT @ 3 * CELLS YM-EVENTS + TO entry value entry ! target entry CELL+ ! tick entry 2 CELLS + !
  1 YM-EVENT-COUNT +! ;
: YM-EVENT! { value reg tick -- } reg YM-CHECK-REG value reg tick YM-QUEUE ;
: YM-INPUT-EVENT! { value port tick -- } port YM-CHECK-PORT value port 16 + tick YM-QUEUE ;
: YM-BUS-TARGET ( address -- target )
  CASE YM-SELECT-ADDRESS OF 18 ENDOF YM-DATA-ADDRESS OF 19 ENDOF -24 THROW ENDCASE ;
: YM-BUS-EVENT! { value address tick -- } value address YM-BUS-TARGET tick YM-QUEUE ;
: YM-TO { tick | entry at -- }
  tick YM-CYCLE @ < IF -24 THROW THEN
  BEGIN YM-EVENT-INDEX @ YM-EVENT-COUNT @ < WHILE
    YM-EVENT-INDEX @ 3 * CELLS YM-EVENTS + TO entry entry 2 CELLS + @ TO at
    at tick > IF tick YM-RAW-TO EXIT THEN
    at YM-RAW-TO entry @ entry CELL+ @ YM-STORE 1 YM-EVENT-INDEX +!
  REPEAT tick YM-RAW-TO ;
: YM-RUN ( clocks -- ) DUP 0< IF -24 THROW THEN DUP 9223372036854775807 YM-CYCLE @ - > IF -24 THROW THEN YM-CYCLE @ + YM-TO ;
: YM-WRITE { value reg tick -- } reg YM-CHECK-REG value reg tick YM-CHECK tick YM-TO value reg YM-STORE ;
: YM-INPUT! { value port tick -- } port YM-CHECK-PORT value port 16 + tick YM-CHECK tick YM-TO value port 16 + YM-STORE ;
: YM-BUS! { value address tick | target -- } address YM-BUS-TARGET TO target value target tick YM-CHECK tick YM-TO value target YM-STORE ;
: YM-PORT@ ( port -- latch drive-mask )
  DUP YM-CHECK-PORT DUP 14 + YM-R@ SWAP 7 YM-R@ SWAP 64 SWAP LSHIFT AND IF 255 ELSE 0 THEN ;
: YM-PIN@ { port | pins -- value }
  port YM-CHECK-PORT YM-PINS port CELLS + @ TO pins
  7 YM-R@ 64 port LSHIFT AND IF port 14 + YM-R@ pins AND ELSE pins THEN ;
: YM-READ { reg tick -- byte }
  reg YM-CHECK-REG tick YM-CYCLE @ < IF -24 THROW THEN tick YM-TO
  reg 14 < IF reg YM-R@ ELSE reg 14 - YM-PIN@ THEN ;
: YM-BUS@ { address tick -- byte }
  address YM-DATA-ADDRESS = IF -21 THROW THEN address YM-SELECT-ADDRESS <> IF -24 THROW THEN
  tick YM-CYCLE @ < IF -24 THROW THEN tick YM-TO
  YM-SELECT @ 16 < IF YM-SELECT @ tick YM-READ ELSE 255 THEN ;
: YM-CHANNEL { channel | amplitude level -- s16level }
  YM-TONE-HIGH channel CELLS + @ 7 YM-R@ 1 channel LSHIFT AND OR 0<>
  YM-LFSR @ 1 AND 7 YM-R@ 8 channel LSHIFT AND OR 0<> AND 0= IF 0 EXIT THEN
  channel 8 + YM-R@ TO amplitude
  amplitude 16 AND IF YM-ENV-LEVEL ELSE amplitude 15 AND DUP IF 2 * 1+ THEN THEN
  CELLS YM-LEVELS + @ ;
: YM-SAMPLE ( -- s16 ) 0 YM-CHANNEL 1 YM-CHANNEL + 2 YM-CHANNEL + 3 / ;
